import React, { PropsWithChildren } from 'react';

import { container } from './MeterBarChartOverlay.sty.js';
import { useMeterBarLayoutSize } from '../../../shared/context/MeterBarLayoutSize.context.js';
import { getChartElementsSizes } from '../../../shared/functions/get-chart-elements-sizes.js';
import { useMeterBarChartData } from '../../context/MeterBarChartDataContext.js';
import { MeterBarChartTooltip } from '../MeterBarChartTooltip/MeterBarChartTooltip.js';

// TODO use shared component for overlays if possible
export const MeterBarChartOverlay = ({ children }: PropsWithChildren) => {
  const { size } = useMeterBarLayoutSize();
  const { chartHeight } = getChartElementsSizes(size);
  const { tooltip: hasTooltip } = useMeterBarChartData();

  return (
    <div
      className={container}
      style={{ height: chartHeight }}
      data-testid="overlay-wrapper"
    >
      {hasTooltip && <MeterBarChartTooltip />}
      {children}
    </div>
  );
};

MeterBarChartOverlay['displayName'] = 'MeterBarChartOverlay';
